// This code has been fully generated by an AI.

package insight

import "fmt"

// Statement is one sentence of an assessment with its tone: "good", "bad"
// or "neutral" (CSS classes of the web layer).
type Statement struct {
	Text string
	Tone string
}

// Tones of a statement.
const (
	ToneGood    = "good"
	ToneBad     = "bad"
	ToneNeutral = "neutral"
)

// Profile holds the personal data the population norms depend on.
type Profile struct {
	Age    int // years, 0 = unknown
	Female bool
}

// Known reports whether the profile can be used for norms.
func (p Profile) Known() bool { return p.Age > 0 }

// VO2max standard ratings by age band (20–29 … 70–79): lower bounds of
// "ausreichend", "gut", "ausgezeichnet" and "hervorragend" (40th, 60th, 80th
// and 95th percentile). Source: The Cooper Institute, as printed in the
// Garmin manuals ("VO2 Max. Standard Ratings").
var (
	vo2Male = [6][4]float64{
		{41.7, 45.4, 51.1, 55.4}, {40.5, 44, 48.3, 54}, {38.5, 42.4, 46.4, 52.5},
		{35.6, 39.2, 43.4, 48.9}, {32.3, 35.5, 39.5, 45.7}, {29.4, 32.3, 36.7, 42.1},
	}
	vo2Female = [6][4]float64{
		{36.1, 39.5, 43.9, 49.6}, {34.4, 37.8, 42.4, 47.4}, {33, 36.3, 39.7, 45.3},
		{30.1, 33, 36.7, 41.1}, {27.5, 30, 33, 37.8}, {25.9, 28.1, 30.9, 36.7},
	}
	vo2Labels = [5]string{"gering", "ausreichend", "gut", "ausgezeichnet", "hervorragend"}
)

// ageBand returns the index of the 10-year band 20–29 … 70–79; ages outside
// use the nearest band.
func ageBand(age int) int {
	return min(max((age-20)/10, 0), 5)
}

// VO2maxNorm rates a VO2max against people of the same age and sex, e.g.
// "für Männer 40–49: ausgezeichnet (hervorragend ab 52,5)".
func VO2maxNorm(p Profile, v float64) (Statement, bool) {
	if !p.Known() || v <= 0 {
		return Statement{}, false
	}
	b := ageBand(p.Age)
	table, who := vo2Male[b], "Männer"
	if p.Female {
		table, who = vo2Female[b], "Frauen"
	}
	level := 0
	for i, lo := range table {
		if v >= lo {
			level = i + 1
		}
	}
	text := fmt.Sprintf("für %s %d–%d: %s", who, 20+10*b, 29+10*b, vo2Labels[level])
	if level < len(table) {
		text += fmt.Sprintf(" (%s ab %s)", vo2Labels[level+1], comma("%.1f", table[level]))
	}
	tone := ToneNeutral
	switch {
	case level >= 3:
		tone = ToneGood
	case level <= 1:
		tone = ToneBad
	}
	return Statement{text, tone}, true
}

// RestingHRNorm places a resting heart rate in the usual adult range of
// 60–100 bpm; lower values are typical for endurance athletes.
func RestingHRNorm(bpm float64) Statement {
	switch {
	case bpm < 40:
		return Statement{"Erwachsene üblich 60–100 bpm; unter 40 bei Ausdauersportlern möglich", ToneNeutral}
	case bpm < 60:
		return Statement{"Erwachsene üblich 60–100 bpm; darunter typisch für Trainierte", ToneGood}
	case bpm <= 100:
		return Statement{"im üblichen Bereich für Erwachsene (60–100 bpm)", ToneNeutral}
	}
	return Statement{"über dem üblichen Bereich für Erwachsene (60–100 bpm)", ToneBad}
}

// SleepNorm compares the average sleep (seconds) of the last 30 days with
// the recommendation of 7–9 h (7–8 h from 65).
func SleepNorm(p Profile, avgS float64) Statement {
	lo, hi := 7.0, 9.0
	if p.Age >= 65 {
		hi = 8
	}
	h := avgS / 3600
	rec := fmt.Sprintf("empfohlen %.0f–%.0f h", lo, hi)
	avg := fmt.Sprintf("⌀ 30 Tage %d:%02d h", int(h), int(avgS/60)%60)
	switch {
	case h < lo:
		return Statement{avg + " – unter der Empfehlung (" + rec + ")", ToneBad}
	case h > hi:
		return Statement{avg + " – über der Empfehlung (" + rec + ")", ToneNeutral}
	}
	return Statement{avg + " – " + rec, ToneGood}
}

// StepsNorm compares the average daily steps of the last 30 days with the
// range where studies see most of the benefit (7,000–10,000; from 60:
// 6,000–8,000).
func StepsNorm(p Profile, avg float64) Statement {
	lo, rng := 7000.0, "7.000–10.000"
	if p.Age >= 60 {
		lo, rng = 6000, "6.000–8.000"
	}
	text := fmt.Sprintf("⌀ 30 Tage %s – Orientierung %s", thousandsDE(avg), rng)
	if avg < lo {
		return Statement{text, ToneBad}
	}
	return Statement{text, ToneGood}
}

func thousandsDE(v float64) string {
	n := int(v + 0.5)
	if n < 1000 {
		return fmt.Sprint(n)
	}
	return fmt.Sprintf("%d.%03d", n/1000, n%1000)
}
